{
  "root_cause": "The focus trap's delayInitialFocus option defers setting initial focus via setTimeout, so focus remains on the opening button when the test checks immediately after the dialog opens.",
  "repair_strategy": "Disable the delayInitialFocus option when creating the focus trap so that initial focus is applied synchronously during activation.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "85fb0980102bd0ea76fa350b8e2df6695a5bf878b5526a6a22d84ca1b8547611",
      "before": "const trap = createFocusTrap('#address-dialog', { onDeactivate: () => { backdrop.hidden = true; } });",
      "after": "const trap = createFocusTrap('#address-dialog', { onDeactivate: () => { backdrop.hidden = true; }, delayInitialFocus: false });"
    }
  ],
  "expected_accessibility_effect": "Keyboard users will receive focus on the street input field immediately when the address dialog opens, enabling them to type without an extra Tab press.",
  "functional_risks": [
    "Potential minor timing difference for assistive technologies that expect a delayed focus, but unlikely to cause adverse effects."
  ],
  "verification_requirements": [
    "After opening the dialog, focus must be on #street.",
    "Typing an address and pressing Save must update the status correctly.",
    "Pressing Escape must close the dialog and return focus to the #open button.",
    "The dialog must still be dismissible via Cancel button."
  ]
}
